// Exact 160x160 Anlogic Logo, including original RGB and transparency.
// Two-clock read: registered cropped address, then original 25-bit pixel.
// All nontransparent source pixels lie in rows 34..127; other rows are zero.
// Pixel table SHA-256 (32768 little-endian 32-bit values): 42d0049297f8830161230e5652fd69d7278487965169dea0cf6aa50f6d9d463b
module anlogic_logo_rom (
    input wire        I_clk,
    input wire [14:0] I_addr,
    output reg [24:0] O_pixel
);
    (* rom_style = "bram" *) reg [9:0] index_rom [0:16383];
    (* rom_style = "bram" *) reg [24:0] palette_rom [0:1023];
    // The first cropped location is transparent. Redirect out-of-range
    // addresses there, keeping the synchronous read free of an output mux.
    wire [13:0] index_addr =
        ((I_addr >= 15'd5440) && (I_addr < 15'd20480)) ?
        I_addr - 15'd5440 : 14'd0;
    // Register the address rather than the index. TD can then absorb this
    // first stage into the index ROM without taking it for the palette ROM.
    reg [13:0] index_addr_d;
    wire [9:0] color_index = index_rom[index_addr_d];
    integer init_index;

    initial begin
        for (init_index = 0; init_index < 16384; init_index = init_index+1)
            index_rom[init_index] = 10'd0;
        for (init_index = 0; init_index < 1024; init_index = init_index+1)
            palette_rom[init_index] = 25'd0;
